item.aggregated_output:
{
  "103:1": "وَٱلْعَصْرِ",
  "103:2": "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ",
  "103:3": "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ"
}

{"connection_id": "BC-0e40f951a172a678c64e", "ref": "1 Clement 38:2", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "rich meet poor person's need", "note": "The commentary's asir withholds resources; this church exhortation tells the rich to supply the poor person's need and the poor to thank God for the provider, turning possession into a reciprocal relation."}
{"connection_id": "BC-bf68395981bc82299d87", "ref": "Didache 1:6", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "alms sweating in the hand", "note": "The commentary's holding hand can be stingy; the Didache asks that alms remain in the hand until the giver knows the recipient, a distinct form of temporary restraint meant to guide giving rather than avoid it."}
{"connection_id": "BC-1a9f29f1644618d6619b", "ref": "Didache 8:1", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "appointed communal fasting days", "note": "The commentary makes fasting one form of patience in a community; the Didache prescribes shared weekly fast days, showing how the act became a repeated group discipline."}
{"connection_id": "BC-5e11f6062437c4936002", "ref": "Martyrdom of Polycarp 11:2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "the martyr's answer to a threat of fire", "note": "The commentary's B013 gloss hears boldness toward Fire; Polycarp tells the proconsul that a brief earthly fire is less than the coming judgment and invites him to proceed. The Christian martyr text makes that boldness a refusal to abandon Christ under execution."}
{"connection_id": "BC-63bcd6557b081b363171", "ref": "Protevangelium of James 8", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Mary removed from temple at puberty", "note": "The commentary calls the newly menstruating girl one kept in the house; the priests seek a guardian for twelve-year-old Mary lest her approaching maturity defile the sanctuary, an early Christian account of seclusion and relocation around puberty."}
{"connection_id": "BC-890dc6bfe7b08bc3824a", "ref": "SBLGNT:1Cor.10.13", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "God limits trial and makes endurance possible", "note": "The commentary joins patient endurance to being under divine care; Paul says God will not allow a trial beyond capacity and will provide a way to endure it."}
{"connection_id": "BC-ef7ee86ca16984ffe105", "ref": "SBLGNT:1Cor.15.37", "target": "sec4", "tradition": "incil", "kind": "karsi_anlati", "basis": "naked grain sown without its mature covering", "note": "The commentary pictures grain guarded by a surrounding husk; Paul says what is sown is a bare grain rather than the body it will have, placing fruitfulness at the point where the old covering is relinquished."}
{"connection_id": "BC-91d2ecc8afbb7f78d2cf", "ref": "SBLGNT:1Cor.7.36", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "guardian decides about young woman's marriage", "note": "The commentary's girl is subject to household control at maturity; one reading of Paul's ambiguous reference to a man's virgin and her passing youth concerns a father's decision about marriage, though the passage can also be read of a betrothed couple."}
{"connection_id": "BC-cfe9da7c23cb185da8d2", "ref": "SBLGNT:1Cor.9.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "athlete exercises self-control for a crown", "note": "The commentary calls fasting a bodily form of holding oneself; Paul says athletes exercise self-control in all things for a perishable crown, then points to an imperishable aim."}
{"connection_id": "BC-1251cc9960b4f4a662e9", "ref": "SBLGNT:1Cor.9.27", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "discipline body and make it a slave", "note": "The commentary sets holding oneself beside being held by another; Paul says he disciplines and enslaves his own body lest he be disqualified, deliberately combining the two positions in one person."}
{"connection_id": "BC-b51cacc06040f71574ed", "ref": "SBLGNT:1John.3.17", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "closing compassion despite means", "note": "The commentary's asir has the means to give but holds them; the letter asks how God's love remains in a person who sees a needy brother yet closes compassion while possessing worldly goods."}
{"connection_id": "BC-93c09340609583734540", "ref": "SBLGNT:1Pet.1.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "faith tested like gold in fire", "note": "The commentary cites the audacious patience of the condemned toward Fire; Peter compares tested faith to gold refined through fire. The shared fire image shifts from punishment to a process that proves faith under trial."}
{"connection_id": "BC-42c5ce930ce4dd491864", "ref": "SBLGNT:1Pet.2.23", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "no threat while suffering", "note": "The commentary sets the person held for killing beside the one who holds himself back; Peter says Christ did not retaliate or threaten when suffering, but entrusted himself to the just judge. It reads restraint under injustice as chosen trust rather than mere helplessness."}
{"connection_id": "BC-e8eaf6469e5a7d4f4196", "ref": "SBLGNT:1Pet.2.23", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "insulted sufferer refrains and entrusts", "note": "The commentary contrasts being held by others with holding oneself; Jesus, under abuse, neither retaliates nor threatens but entrusts judgment to God, giving the captive person's restraint agency."}
{"connection_id": "BC-6ef596cbd5240aed6c7c", "ref": "SBLGNT:1Pet.3.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "God's eyes and ears attend the righteous", "note": "The commentary says the waiting person is under God's eyes; this letter applies the scriptural formula of the Lord's eyes toward the righteous and ears toward their prayer, giving the watched person a hearing as well."}
{"connection_id": "BC-737b5953327a32ce1660", "ref": "SBLGNT:1Pet.4.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "self-control and prayer near the end", "note": "The commentary links the passing time, the held self and an exception marked by prayer; Peter says the end is near and therefore calls believers to sound judgment and sobriety for prayer."}
{"connection_id": "BC-c7ef17c70e7cb75ccd6c", "ref": "SBLGNT:1Pet.5.9", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "firm faith amid shared suffering", "note": "The commentary extends patience from one person to a mutually enduring community; Peter tells believers to resist firmly in faith, knowing the same sufferings are being completed among their brothers and sisters elsewhere."}
{"connection_id": "BC-6d7af5afd1991a889429", "ref": "SBLGNT:1Thess.5.11", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "mutually encourage and build up", "note": "The commentary makes patience something believers counsel each other to practice; Paul directly tells the community to encourage one another and build each other up."}
{"connection_id": "BC-c1336115df5fcefe1bbe", "ref": "SBLGNT:1Thess.5.14", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "patience with the weak", "note": "The commentary makes sabr something believers enjoin on one another; Paul tells the congregation to encourage the fainthearted, help the weak, and be patient with everyone. Its context makes patience a shared practice toward vulnerable people."}
{"connection_id": "BC-3b3bcc14661406f7b4b5", "ref": "SBLGNT:1Thess.5.14", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "warn, encourage, support, be patient with all", "note": "The commentary's patience is a shared duty rather than an isolated virtue; Paul orders the community to admonish the idle, encourage the fainthearted, help the weak and be patient toward all."}
{"connection_id": "BC-f6081c73dec8a5310ab0", "ref": "SBLGNT:2Cor.6.5", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "imprisonment and hunger together", "note": "The commentary juxtaposes enforced custody with endurance; Paul lists imprisonments alongside hard work, sleeplessness and hunger among apostolic hardships, preceding the patience named in the next verse."}
{"connection_id": "BC-94bc55493223a5c382bd", "ref": "SBLGNT:2Cor.6.6", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "patience and kindness in hardship", "note": "The commentary's patient community has to answer distress with good action; Paul follows the preceding list of prisons and deprivations by naming patience and kindness among the qualities of his ministry."}
{"connection_id": "BC-eafa55426c6651c33e72", "ref": "SBLGNT:2Cor.9.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "giving without compulsion", "note": "The commentary sets forced oath beside the tight hand; Paul tells each person to give as decided in the heart, not under compulsion, so the release of goods is neither hoarding nor coercion."}
{"connection_id": "BC-14f0da066121e5f7cfc9", "ref": "SBLGNT:2Pet.3.11", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "conduct measured against coming fire", "note": "The commentary ties daring toward fire to a ruinous moral choice; after describing the world's fiery dissolution, Peter asks what holy and godly conduct is required, reversing reckless exposure into ethical preparation."}
{"connection_id": "BC-d9da839fedba19db0b54", "ref": "SBLGNT:2Pet.3.9", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "delayed judgment as patience for repentance", "note": "The commentary has the prophet wait for the Lord's judgment; Peter says the Lord's apparent delay is patience, allowing people time to reach repentance rather than perish. It makes waiting itself a merciful postponement of loss."}
{"connection_id": "BC-ea42649ee6908ce34112", "ref": "SBLGNT:2Pet.3.9", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "God's patience delays destruction", "note": "The commentary says waiting occurs under God's watch and ends in judgment; this verse interprets apparent divine delay as patience toward people, giving them time to repent rather than perish."}
{"connection_id": "BC-bd33f1deeac515a96e58", "ref": "SBLGNT:Acts.13.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "community fasting while discerning direction", "note": "The commentary extends patient holding from a person to a group; the Antioch church worships and fasts when the Spirit speaks, placing shared restraint beside guidance and action."}
{"connection_id": "BC-0cb142683a234123e745", "ref": "SBLGNT:Acts.16.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "prisoners pray and sing while bound", "note": "The commentary's captive can still practice an active form of patience; Paul and Silas pray and sing hymns at midnight in prison while other prisoners listen."}
{"connection_id": "BC-d696ca1ccd839d856c80", "ref": "SBLGNT:Acts.23.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "oath-bound abstinence used to plan murder", "note": "The commentary calls fasting a type of self-restraint yet also depicts forced oath and a person held for death; conspirators bind themselves by an oath to eat and drink nothing until they kill Paul, turning restraint into violence."}
{"connection_id": "BC-cad4da8f0ca69beedd3f", "ref": "SBLGNT:Acts.5.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "part of sale proceeds held back secretly", "note": "The commentary's holding hand can turn into deception; Ananias keeps part of the proceeds while presenting a gift as though complete, so the retained amount is tied to false speech."}
{"connection_id": "BC-4fbb2a4f3a1610f8279c", "ref": "SBLGNT:Acts.5.4", "target": "sec4", "tradition": "incil", "kind": "karsi_anlati", "basis": "property remained at the giver's disposal", "note": "The commentary's tight hand is blameworthy when it refuses a rightful good; Peter says the field and its price remained under Ananias's authority, specifying that his wrongdoing was deceit rather than mere retention."}
{"connection_id": "BC-03ba647947364c992108", "ref": "SBLGNT:Acts.7.60", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "asking that a sin not be held against killers", "note": "The commentary says each soul is held to what it has earned; while being stoned, Stephen asks the Lord not to hold this sin against his killers. The dying victim's plea reverses the image of deeds holding a person liable."}
{"connection_id": "BC-681a909b2f0d4863f5be", "ref": "SBLGNT:Acts.8.32", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "Isaiah's silent servant read aloud", "note": "The commentary's image joins a person held for slaughter to self-restraint; Acts quotes Isaiah's lamb led to slaughter and silent before its shearer. The quotation carries that double image into a Christian scene of scriptural reading; Philip's interpretation is stated separately in Acts 8:35."}
{"connection_id": "BC-354f1c2c67726a360bfb", "ref": "SBLGNT:Acts.8.35", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "the servant interpreted as good news about Jesus", "note": "The commentary fuses being held with holding oneself back; Philip begins from the Isaiah passage and proclaims Jesus. This New Testament interpretation makes the silent, slaughtered servant a Passion reading, extending the connection beyond the quotation in Acts 8:32."}
{"connection_id": "BC-4ffb8d2d63f1cd3f886b", "ref": "SBLGNT:Col.3.13", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "bear with and forgive one another", "note": "The commentary calls believers to recommend patience to one another; Colossians makes that reciprocal by asking each person to bear with and forgive another after a complaint."}
{"connection_id": "BC-a01090d1486ff3caf199", "ref": "SBLGNT:Col.3.16", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "teach and admonish one another", "note": "The commentary says the saved community commends truth and patience to its members; Colossians commands mutual teaching and admonition with wisdom, turning shared conviction into speech."}
{"connection_id": "BC-65bbb308783dbefe34da", "ref": "SBLGNT:Eph.4.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "patience while bearing one another", "note": "The commentary extends the held self to a community that holds together; Ephesians names patience and bearing with one another in love as conduct worthy of the calling."}
{"connection_id": "BC-0c51b054f998f1ea2015", "ref": "SBLGNT:Eph.4.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "truth spoken because members belong together", "note": "The commentary joins truth to reciprocal counsel within the group; Ephesians tells each person to speak truth to a neighbor because believers are members of one another."}
{"connection_id": "BC-bef71b9728cbc3068d74", "ref": "SBLGNT:Gal.6.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "community carries one another's burdens", "note": "The commentary moves from one person's held self to shared endurance; Paul commands believers to bear one another's burdens, giving collective patience a practical action."}
{"connection_id": "BC-dd1f73a07e9deafe8f44", "ref": "SBLGNT:Gal.6.9", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "doing good and not tiring", "note": "The commentary pairs righteous action with reciprocal counsel to patience; Paul joins not growing weary in doing good with the promise of harvest for those who do not give up. The link makes ethical work a practice sustained through waiting."}

{"connection_id": "BC-771758346464b59aee75", "ref": "SBLGNT:Heb.10.24", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "mutually spurring love and good works", "note": "The commentary says believers repeatedly counsel one another and do righteous deeds; Hebrews asks the community to consider how to stir one another to love and good works. This is a distinct reciprocal-action detail from the encouragement in Hebrews 10:25."}
{"connection_id": "BC-21600a8c63c86350eace", "ref": "SBLGNT:Heb.10.24", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "spur one another to love and good works", "note": "The commentary's mutual counsel sits beside faith and righteous action; Hebrews asks members to consider how to provoke one another toward love and good deeds."}
{"connection_id": "BC-bfdd7e97be97294ec34a", "ref": "SBLGNT:Heb.10.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "mutual encouragement as the Day approaches", "note": "The commentary's repeated tawāṣaw is reciprocal counsel; Hebrews tells believers to encourage one another, increasingly as they see the Day approaching. It locates mutual support inside an expectation that calls for endurance."}
{"connection_id": "BC-5871a754e64a5503bd4a", "ref": "SBLGNT:Heb.10.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "mutual encouragement as the day approaches", "note": "The commentary expands restraint to a persevering group; Hebrews warns against abandoning assembly and calls for encouraging one another as the day draws near."}
{"connection_id": "BC-8ba76d7b6eba0d9c83ed", "ref": "SBLGNT:Heb.10.34", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "care for prisoners despite property loss", "note": "The commentary sets imprisoned people beside the hand that guards possessions; Hebrews recalls sympathy for prisoners and joyful acceptance of property being seized because the community knew of a better possession."}
{"connection_id": "BC-1ff62eedb66b0ddbf693", "ref": "SBLGNT:Heb.10.36", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "endurance before receiving the promise", "note": "The commentary calls sabr waiting for the Lord's judgment; Hebrews says endurance is needed after doing God's will in order to receive what was promised. It connects patience to a delayed divine outcome, not passive time alone."}
{"connection_id": "BC-09f135234ba6b431d125", "ref": "SBLGNT:Heb.10.36", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "endurance while awaiting promise", "note": "The commentary tells the prophet to wait for the Lord's judgment; Hebrews says believers need endurance to do God's will and receive what was promised, connecting delay with obedient action."}
{"connection_id": "BC-7455741b287fbb884fc8", "ref": "SBLGNT:Heb.12.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "endured the cross for a future joy", "note": "The commentary contrasts a captive facing death with voluntary patience; Jesus endures the cross and shame for the joy set before him, giving purpose to restraint under execution."}
{"connection_id": "BC-4c08faf8e1928dfc5134", "ref": "SBLGNT:Heb.13.3", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "remember prisoners as bound with them", "note": "The commentary's person held by others remains part of the patient community; Hebrews tells readers to remember prisoners as though bound alongside them, turning shared endurance into solidarity."}
{"connection_id": "BC-2e25f3097adcd09847ef", "ref": "SBLGNT:Heb.2.15", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "enslavement to fear of death", "note": "The commentary calls the human captive to death; Hebrews says people are held in lifelong slavery through fear of death, and its surrounding argument presents Christ as liberator. This supplies a Christian account of death as captivity rather than only an individual fate."}
{"connection_id": "BC-8e4a2ecdf005a138ebb4", "ref": "SBLGNT:Heb.3.13", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "exhort one another each day", "note": "The commentary makes patience something believers commend to each other; Hebrews commands daily mutual exhortation lest any heart be hardened by sin."}
{"connection_id": "BC-6739cf3878f9fbe70987", "ref": "SBLGNT:Heb.6.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "faith and patience inheriting the promise", "note": "The commentary's exception begins with belief and ends with mutual counsel to sabr; Hebrews urges imitation of those who inherit the promises through faith and patience. This gives the faith-patience pairing a concrete inheritance horizon."}
{"connection_id": "BC-91c7d13f908f0d37bbe9", "ref": "SBLGNT:Heb.6.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "faith and patience inherit promise", "note": "The commentary puts faith beside patience in the saved community; Hebrews tells readers to imitate those who inherit promises through faith and patience."}
{"connection_id": "BC-fe087be11781035d1bcb", "ref": "SBLGNT:Jas.1.19", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "slow speech and slow anger", "note": "The commentary opposes the human being's quick distress to holding the self; James commands everyone to be quick to hear but slow to speak and slow to anger."}
{"connection_id": "BC-72f73f766a3aed7814a9", "ref": "SBLGNT:Jas.1.3", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "faith tested into endurance", "note": "The commentary puts faith and patience together as the exception to human loss; James says the testing of faith produces steadfastness, explaining how the two qualities meet in affliction."}
{"connection_id": "BC-1a6db1fd3aa33387eacf", "ref": "SBLGNT:Jas.1.4", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "endurance prevents lack", "note": "The commentary describes humanity as in loss unless patience joins faith and good action; James asks that steadfastness complete its work so the believer may be complete and lack nothing."}
{"connection_id": "BC-105b540a841f2823eef2", "ref": "SBLGNT:Jas.2.16", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "good wishes without food or clothing", "note": "The commentary makes withheld goods a failure of the hand; James asks what good it does to wish warmth and fullness to a needy person without providing bodily necessities."}
{"connection_id": "BC-6cbadfd0eeaa89c4c4e4", "ref": "SBLGNT:Jas.5.10", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "prophets model suffering and patience", "note": "The commentary's prophet is told to endure while awaiting the Lord's decision; James names the prophets who spoke in the Lord's name as examples of suffering and patience."}
{"connection_id": "BC-37a9c59869b973ec8844", "ref": "SBLGNT:Jas.5.11", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "Job's endurance and the Lord's outcome", "note": "The commentary treats patience as waiting for God's judgment; James names Job's endurance and points readers to the Lord's compassionate purpose. This Christian reading makes Job's suffering a model of endurance whose outcome rests with God."}
{"connection_id": "BC-4c9a0f0d2d7290a89e1d", "ref": "SBLGNT:Jas.5.11", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "Job's endurance and divine outcome", "note": "The commentary joins waiting under pain to divine care; James calls those who endured blessed and points to Job's endurance and the Lord's compassionate outcome."}
{"connection_id": "BC-350688527bd06034c31d", "ref": "SBLGNT:Jas.5.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "truthful speech in place of oaths", "note": "The commentary's oath scene makes another person control a man's speech; James forbids oath-taking and asks for plain yes and no, a response to the moral vulnerability of sworn speech."}
{"connection_id": "BC-52e66a448abc6afcaaa1", "ref": "SBLGNT:Jas.5.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "the patient farmer awaiting harvest", "note": "The commentary's waiting sabr looks toward the Lord's judgment; James compares it with a farmer patiently awaiting the precious crop through the early and late rains. The agrarian image makes delay a season that must be borne."}
{"connection_id": "BC-7d6ef051f83a4ec6bb58", "ref": "SBLGNT:Jas.5.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "farmer waits for precious crop", "note": "The commentary's patience includes waiting rather than merely suppression; James asks believers to be patient until the Lord's coming like a farmer awaiting the crop and its rains."}
{"connection_id": "BC-5c37402b8d3d1ae28c79", "ref": "SBLGNT:John.12.24", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "grain must die to bear fruit", "note": "The commentary's B010 source presents grain kept safe in its husk; Jesus' grain of wheat remains alone unless it falls into the earth and dies, then bears much fruit. The image offers a contrary valuation of preservation: fruitful life requires surrender rather than enclosure."}
{"connection_id": "BC-740fc1519042690ed896", "ref": "SBLGNT:John.12.24", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "grain must leave solitary intactness", "note": "The commentary's grain remains protected in its covering; Jesus says a grain that does not fall into the earth and die remains alone, while dying makes it fruitful, a contrary claim about when protected seed must be released."}
{"connection_id": "BC-4a5147a10aaf2b14d48a", "ref": "SBLGNT:Luke.12.18", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "barns built to contain surplus", "note": "The commentary includes grain kept in protection and wealth held back; the rich farmer plans larger barns for his grain and goods, joining storage to the closed-hand danger."}
{"connection_id": "BC-a839f215195ea54ea646", "ref": "SBLGNT:Luke.12.19", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "stored goods mistaken for long rest", "note": "The commentary opposes prudent waiting to a hand that hoards; the rich farmer tells his soul to rest for many years on stored goods, an imagined secure future overturned by the divine demand in the next verse."}
{"connection_id": "BC-7af86eff40373092dff3", "ref": "SBLGNT:Luke.12.20", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "stored harvest and life demanded", "note": "The commentary joins the withholding of wealth to the soul pledged for what it earns; in Jesus' parable the rich fool enlarges his barns, then has his life demanded that night. The verse makes material accumulation unable to retain life."}
{"connection_id": "BC-691be91749fadf860d9e", "ref": "SBLGNT:Luke.12.20", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "stored grain cannot secure the soul", "note": "The commentary's B010 source describes grain guarded in its husk, and its B006 image is wealth held back; Jesus' rich fool stores abundant produce but is told his life is required that night. The parable contrasts preserved goods with a life that cannot be kept."}
{"connection_id": "BC-b7c293f8b6224c5dbe12", "ref": "SBLGNT:Luke.12.20", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "soul demanded after goods stored", "note": "The commentary's possessor is still a mortal held to account; God demands the rich farmer's life that night and asks who will own the stored goods, overturning the fantasy of secure possession."}
{"connection_id": "BC-55b569dc512cf208ad59", "ref": "SBLGNT:Luke.12.37", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "the returning master finds servants watching", "note": "The commentary says the one who waits is under observation; Jesus blesses servants whom their returning master finds awake and watching. This gives the watched wait an eschatological household scene and a reward for readiness."}
{"connection_id": "BC-2c33254ff32c6877361e", "ref": "SBLGNT:Luke.13.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "the fruitless tree facing judgment", "note": "The commentary says humanity is in loss except for those who do righteous deeds; in Jesus' parable the owner reports three years of seeking fruit from a tree that bears none and orders it cut down. It gives fruitlessness a specific scene of impending loss."}
{"connection_id": "BC-d8f89eee871d993207c5", "ref": "SBLGNT:Luke.13.8", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "delaying the felling for another year", "note": "The commentary frames sabr as waiting for the Lord's judgment; in the same parable the gardener asks that the tree be left one more year to be dug around and fertilized. The delay gives the condemned tree time to bear fruit."}
{"connection_id": "BC-898da5f023ca73b3293a", "ref": "SBLGNT:Luke.15.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "the father releases the son's property", "note": "The commentary's B006 source gives a father withholding his child's property; the younger son asks for his share and the father divides his property between the sons. The reversed transfer makes the parent-child relation a specific counterexample to retention, though the parable develops a different issue."}
{"connection_id": "BC-5eb23a8212976b6fb979", "ref": "SBLGNT:Luke.15.12", "target": "sec4", "tradition": "incil", "kind": "karsi_anlati", "basis": "father divides property at son's request", "note": "The commentary's father withholds a child's goods; the younger son requests his share and the father divides the estate, a narrative reversal of paternal withholding."}
{"connection_id": "BC-f430b91e19f142796c28", "ref": "SBLGNT:Luke.15.31", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "father says all his goods are son's", "note": "The commentary raises the possibility of a father retaining a son's property; the father assures the elder son that everything he has is his, distinguishing possession from a closed paternal hand."}
{"connection_id": "BC-1f4a3a4a44859932072b", "ref": "SBLGNT:Luke.16.19", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "feasting rich man before reversal", "note": "The commentary links the human hand's surplus to later loss; the rich man dresses luxuriously and feasts every day while Lazarus lies at his gate in the next verse, establishing what could have been shared."}
{"connection_id": "BC-6b23d6d2b11b675ca1a4", "ref": "SBLGNT:Luke.16.21", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "poor man denied falling crumbs", "note": "The commentary includes the hand that withholds available goods; Lazarus longs for the crumbs from the rich man's table, so the later flame follows a specific unshared surplus."}
{"connection_id": "BC-5d1ad29a458f8b882e9d", "ref": "SBLGNT:Luke.16.24", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "wealth holder begs relief from flame", "note": "The commentary places withholding beside daring toward fire; the rich man who ignored Lazarus now begs for a finger dipped in water to cool him in the flame, reversing who needs the other's hand."}
{"connection_id": "BC-96022bce539206cf871f", "ref": "SBLGNT:Luke.16.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "reversal of comfort and agony", "note": "The commentary's gain-hoarding person becomes the one held to loss; Abraham tells the rich man that Lazarus now receives comfort while he is in anguish, explaining the reversal after their lifetimes."}

{"connection_id": "BC-17e1c5f47594a78c4572", "ref": "SBLGNT:Luke.21.19", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "gain life through endurance", "note": "The commentary calls humanity lost except for those who practice patience; Jesus tells persecuted hearers that by their endurance they will gain their lives, linking loss and preservation directly."}
{"connection_id": "BC-1b3ada8e9c23305b36b7", "ref": "SBLGNT:Luke.22.31", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "Satan seeks to sift disciples like wheat", "note": "The commentary's grain is kept in its covering and the community must endure pressure; Jesus says Satan has demanded to sift the disciples like wheat, turning grain processing into an image of testing the group."}
{"connection_id": "BC-7d452d07e44a1f9cc7cf", "ref": "SBLGNT:Luke.22.32", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "prayer protects faith through sifting", "note": "The commentary's waiting believer is under protective divine attention and encourages others; Jesus says he has prayed that Peter's faith not fail and tells him to strengthen his brothers after he turns back."}
{"connection_id": "BC-bd749bd16f3ffd6e257d", "ref": "SBLGNT:Luke.4.18", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "proclamation of release to captives", "note": "The commentary's captive is held toward death; Jesus' reading of Isaiah announces release to captives, supplying a counter movement to the image of enforced confinement."}
{"connection_id": "BC-2e29857c2c1b54b36ca7", "ref": "SBLGNT:Matt.16.26", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "profit that loses the soul", "note": "The commentary pairs a bad purchase with loss and fire; Jesus asks what profit there is in gaining the whole world while forfeiting one's life, a pointed counterpart to buying error at the cost of guidance."}
{"connection_id": "BC-ca739e23be1ed2064ecb", "ref": "SBLGNT:Matt.18.30", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "debtor jailed until payment", "note": "The commentary says a person can be held as security for what he has earned; the unforgiving servant imprisons a fellow debtor until he pays, making financial liability literal captivity."}
{"connection_id": "BC-2559d7038e8d86e622e9", "ref": "SBLGNT:Matt.18.34", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "unforgiving creditor made the detained debtor", "note": "The commentary contrasts the hand that withholds with the one who becomes held; the master hands the unmerciful servant over to jailers until his debt is paid, reversing his role in the previous imprisonment."}
{"connection_id": "BC-598788c9d370a0ea0f42", "ref": "SBLGNT:Matt.25.36", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "visit the one held in prison", "note": "The commentary places the captive beside the hand that may withhold good; the righteous are commended for coming to the speaker while he was in prison, an action addressed specifically to the held person."}
{"connection_id": "BC-30f5469e9b048a6b669d", "ref": "SBLGNT:Matt.25.41", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "fire after withheld care", "note": "The commentary places a withholding hand beside fire as a dire end; the judgment scene sends those on the left to eternal fire, with their failure to feed and welcome specified in the next verse."}
{"connection_id": "BC-13f23c0a545f533ff1d4", "ref": "SBLGNT:Matt.25.42", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "failure to feed and give drink", "note": "The commentary treats the withholding hand as a moral failure; the condemned are told they gave no food or drink to the hungry and thirsty, making a withheld gift decisive in judgment."}
{"connection_id": "BC-657f05179054c13dfec6", "ref": "SBLGNT:Matt.25.43", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "failure to visit prisoner", "note": "The commentary's withholding hand and detained person meet in one moral scene; the condemned are told they did not visit the speaker when he was sick or in prison."}
{"connection_id": "BC-38ad3ce975d73d308fc2", "ref": "SBLGNT:Matt.26.63", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "adjuration at Jesus' hearing", "note": "The commentary's B002 gloss includes compelling someone by an oath; the high priest adjures detained Jesus by the living God to say whether he is the Messiah. Matthew's detail is an oath-bound demand for testimony, though Jesus is adjured to answer rather than made to swear an oath himself."}
{"connection_id": "BC-1b5b4ab001e4fa4df6d1", "ref": "SBLGNT:Matt.26.63", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "high priest adjures silent prisoner", "note": "The commentary's captive is made to swear and faces death; the high priest adjures the previously silent Jesus by the living God to answer about his identity during the trial."}
{"connection_id": "BC-a9a9d90df1f8245fb62e", "ref": "SBLGNT:Matt.27.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "bound and delivered to the governor", "note": "The commentary's B002 gloss is a person detained for death; Matthew says the leaders bound Jesus and delivered him to Pilate, leading into the execution narrative. This gives the passive, externally held figure a concrete Passion setting."}
{"connection_id": "BC-1846fa38bf93be5a85d2", "ref": "SBLGNT:Matt.3.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "wheat gathered after chaff separation", "note": "The commentary imagines grain sheltered in its covering; the winnower separates wheat from chaff and gathers the grain into storage, showing the covering removed when preservation takes a new form."}
{"connection_id": "BC-5299d58f5e2075515a58", "ref": "SBLGNT:Matt.4.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "Jesus' voluntary fast", "note": "The commentary's B015 gloss treats fasting as one form of self-restraint; Matthew says Jesus fasts forty days and nights and becomes hungry. This gives the restraint a sustained Christian practice in a wilderness testing scene."}
{"connection_id": "BC-8ce283024b07f27cd55e", "ref": "SBLGNT:Matt.4.2", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "long fast brings real hunger", "note": "The commentary identifies fasting as one kind of patience; Jesus fasts forty days and nights and becomes hungry, presenting abstinence as bodily restraint with a cost."}
{"connection_id": "BC-be6f4a09a801ab5958af", "ref": "SBLGNT:Matt.4.4", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "fasting answered with God's word", "note": "The commentary's fast is a kind of self-restraint oriented toward divine judgment; when hungry after fasting, Jesus answers temptation by saying human life depends on God's word as well as bread."}
{"connection_id": "BC-efd789bd703fe18b5b1f", "ref": "SBLGNT:Matt.5.37", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "plain yes and no rather than sworn control", "note": "The commentary's man is made to swear by someone else; Jesus directs hearers toward plain yes and no, supplying a form of truthful speech that does not depend on an imposed oath."}
{"connection_id": "BC-51035f588b5574ecb8c4", "ref": "SBLGNT:Matt.6.16", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "fasting can become public display", "note": "The commentary treats fasting as an inward holding of the self; Jesus warns fasters against disfiguring their faces to be seen by others, distinguishing the act from theatrical self-display."}
{"connection_id": "BC-995fa1bf5f03869b7d46", "ref": "SBLGNT:Matt.7.9", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "father asked for bread does not give stone", "note": "The commentary imagines a father's hand controlling what his child receives; Jesus' question assumes a father responds to a son's request for bread with food rather than a useless stone."}
{"connection_id": "BC-df1b366e1b8a8e757002", "ref": "SBLGNT:Matt.9.15", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "fast during bridegroom's absence", "note": "The commentary connects patience with waiting and fasting with self-restraint; Jesus says the wedding guests will fast when the bridegroom is taken away, giving voluntary abstinence the time of an absence."}
{"connection_id": "BC-e9f51347d01373dc360e", "ref": "SBLGNT:Rev.13.10", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "captivity and the endurance of saints", "note": "The commentary opposes the person held by others to the one who practices patience; this verse names captivity and sword death, then identifies the saints' endurance and faith in that situation."}
{"connection_id": "BC-667701abc607eae44771", "ref": "SBLGNT:Rev.14.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "faith, obedience, endurance", "note": "The commentary's exception joins belief, righteous deeds, and mutual exhortation to patience; Revelation calls the endurance of the saints those who keep God's commands and faith in Jesus. It brings the same cluster of fidelity and perseverance into an apocalyptic community."}
{"connection_id": "BC-f271afe018e02a485c18", "ref": "SBLGNT:Rev.14.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "endurance, commandments, faith", "note": "The commentary groups faith, good action and mutual patience as the exception to loss; Revelation identifies the saints' endurance with keeping God's commandments and faith in Jesus."}
{"connection_id": "BC-78add3eab6473d24c7e2", "ref": "SBLGNT:Rev.2.10", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "prison, trial, faithfulness to death", "note": "The commentary's prisoner is held toward death and the believer is urged to endure; the church is warned of imprisonment and called to remain faithful even to death."}
{"connection_id": "BC-5a2771f8424c04e8fd05", "ref": "SBLGNT:Rev.3.10", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "kept word of endurance, then guarded from trial", "note": "The commentary links mutual persistence with being kept under divine eyes; the risen speaker promises to keep a faithful community from the hour of trial because it has kept his word of endurance."}
{"connection_id": "BC-f0f2b02521486d5b91a3", "ref": "SBLGNT:Rom.12.12", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "patient in affliction and constant in prayer", "note": "The commentary's waiting person restrains panic under God's eyes; Paul joins patience in suffering to persistence in prayer, making endurance an active appeal."}
{"connection_id": "BC-4294641a8dab1b3b90dd", "ref": "SBLGNT:Rom.2.4", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "divine forbearance meant for repentance", "note": "The commentary treats patience as a held response to wrongdoing; Paul says God's kindness, forbearance and patience are meant to lead the human being to repentance, extending restraint to God."}
{"connection_id": "BC-b233a0fa806b1711f582", "ref": "SBLGNT:Rom.2.5", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "storing wrath through stubbornness", "note": "The commentary's person can hoard what becomes loss at judgment; Paul says a hard, unrepentant heart stores up wrath for the day of God's judgment, a negative counterpart to storing goods."}
{"connection_id": "BC-eaff7283a5a95a65eac2", "ref": "SBLGNT:Rom.2.7", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "perseverance in doing good", "note": "The commentary pairs righteous deeds with patience; Paul describes those who seek glory and immortality through endurance in good work and receive eternal life. It joins ethical action and perseverance in a judgment setting."}
{"connection_id": "BC-e532a6632c2a94708ef8", "ref": "SBLGNT:Rom.8.25", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "patient waiting for unseen hope", "note": "The commentary's patience means waiting for a divine outcome one cannot yet see; Paul says believers wait for what they do not see through endurance."}
{"connection_id": "BC-132f3de0a08e7a0c5e8d", "ref": "SBLGNT:Rom.9.22", "target": "sec4", "tradition": "incil", "kind": "motif", "basis": "divine patience toward those facing destruction", "note": "The commentary sets patient restraint beside judgment on the human being; Paul describes God enduring with much patience vessels of wrath prepared for destruction, delaying the punitive end."}
{"connection_id": "BC-0980f17e5003f268a8c5", "ref": "Shepherd of Hermas, Similitude 5.3", "target": "sec4", "tradition": "incil", "kind": "yorum_gelenegi", "basis": "fasting savings given to needy people", "note": "The commentary places fasting beside the hand that can withhold goods; Hermas' instruction directs a faster to give the cost of the uneaten meal to someone in need, making bodily restraint release resources."}
{"connection_id": "BC-46e26d419bcfb3c7500a", "ref": "2 Maccabees 7:20", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "mother strengthens sons through execution", "note": "The commentary makes patience a virtue commended between people; the mother watches her seven sons die in one day and bears it with courage because of hope in the Lord, a family form of shared endurance."}
{"connection_id": "BC-c7f5e888648a24dd9a27", "ref": "2 Maccabees 7:21", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "a mother encourages the condemned", "note": "The commentary makes mutual counsel to patience part of the exception from loss; the mother in 2 Maccabees encourages each son as they face execution for refusing forbidden food. Her words make steadfastness communal under coercion and orient it toward resurrection hope."}
{"connection_id": "BC-d9ca9d89303c10c2a36c", "ref": "2 Maccabees 7:9", "target": "sec4", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "facing lethal torment for covenant hope", "note": "The commentary's inverted patience is rash boldness before fire after rejecting guidance; the tortured brother tells his killer that God will raise those who die for God's laws, a contrary reason for accepting death."}
{"connection_id": "BC-9533912f04999f3794ea", "ref": "4 Maccabees 1:1", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "reason governing the passions", "note": "The commentary's B001 gloss is holding the self back from panic; 4 Maccabees opens by asking whether devout reason rules the passions. Its philosophical frame makes self-restraint the governing question for the martyr stories that follow."}
{"connection_id": "BC-ce4a9688e8160bfb3ea2", "ref": "4 Maccabees 1:1", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "devout reason rules passions", "note": "The commentary treats patience as holding the self even under pressure; the work opens by arguing that pious reason governs passions, a Jewish interpretation of disciplined endurance developed in its martyr stories."}
{"connection_id": "BC-a4eb901c689cbdccbb6a", "ref": "4 Maccabees 6", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "refusing coerced food at the cost of death", "note": "The commentary distinguishes self-restraint from being restrained by another and calls fasting a kind of sabr; Eleazar is pressured to eat forbidden meat but accepts torture rather than violate the law. The martyr narrative makes bodily abstention an act of chosen fidelity under lethal coercion."}

{"connection_id": "BC-86ddac0036b3b85a1a32", "ref": "Berakhot 60b", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "reinterpreting apparent loss as hidden good", "note": "The commentary presents humanity as being in loss and patience as waiting for God's decree; Rabbi Akiva interprets a chain of setbacks as for the good after those very losses protect his life. This Jewish story preserves trust without pretending the setbacks initially look beneficial."}
{"connection_id": "BC-8f21c6ab3e0dc5f173fc", "ref": "Berakhot 6b", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "reward of fasting is charity", "note": "The commentary pairs fasting as self-restraint with the ethical problem of withholding; this rabbinic maxim makes charity the reward or fruit of a fast, interpreting abstinence through what the hand gives."}
{"connection_id": "BC-5a3a7da18b830ee7f1a9", "ref": "Genesis Rabbah 56:8", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "Isaac's willing binding", "note": "The commentary's B002 image is a person bound for killing; Genesis Rabbah has Isaac ask to be bound securely so that he will not flinch and invalidate the offering. The midrash makes external restraint also an act of the victim's self-control."}
{"connection_id": "BC-0cc26d18bf486efa314b", "ref": "Mishnah Avot 4:1", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "subduing one's inclination", "note": "The commentary presents sabr as self-restraint; Ben Zoma interprets Proverbs' ruler of his spirit as the truly mighty person who subdues his inclination. This Jewish reading turns the proverb's city-conquest comparison into inward mastery."}
{"connection_id": "BC-98d2d6bbd7e346ba105e", "ref": "Mishnah Avot 4:1", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "strength as conquering inclination", "note": "The commentary defines patience as holding the self rather than being held; the saying calls one who conquers his own inclination mighty, interpreting power as inward mastery."}
{"connection_id": "BC-fad26e920b86566b1401", "ref": "Mishnah Ketubot 4:4", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "father's authority over minor daughter's goods and vows", "note": "The commentary joins a father controlling a child's property with a young girl kept at home; this legal tradition enumerates a father's rights over his minor daughter's betrothal, earnings, finds and vows, clarifying how household custody includes economic control."}
{"connection_id": "BC-a149b14139149b422de6", "ref": "Mishnah Ta'anit 2:1", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "communal fast judged by changed deeds", "note": "The commentary broadens patience to a community and calls fasting a form of restraint; this fast-day exhortation says the people of Nineveh were heeded for changed deeds, making a gathered fast accountable to conduct."}
{"connection_id": "BC-d24de116eec629e81a4a", "ref": "Mishnah Yoma 8:1", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "fasting given bodily prohibitions", "note": "The commentary equates fasting with self-restraint; the Mishnah specifies Yom Kippur's abstentions, including eating and drinking. It gives the Torah's self-affliction a concrete ritual practice and limits what the word alone states."}
{"connection_id": "BC-ea8b0a1d9898c7ae8a16", "ref": "Sirach 18:30", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "restraining appetite", "note": "The commentary's B001 gloss explains sabr as holding the self back; Sirach tells the reader not to follow base desires but to restrain appetites. This gives the inward act a concrete ethical object beyond merely waiting."}
{"connection_id": "BC-74dfe11f358310892890", "ref": "Sirach 18:30", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "restrain appetites", "note": "The commentary defines patience as holding one's own self; Sirach tells the hearer not to follow desires but to restrain appetites, directing the holding inward."}
{"connection_id": "BC-bf3745cd11111964a650", "ref": "Sirach 2:4", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "patient acceptance of humiliating change", "note": "The commentary asks the afflicted person to wait under God's judgment rather than cry out; Sirach tells the hearer to accept what befalls him and be patient in humiliation."}
{"connection_id": "BC-00121d1c07a49aa0e3af", "ref": "Sirach 2:5", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "gold tested in fire", "note": "The commentary's B013 gloss develops audacity toward Fire; Sirach says gold is tested by fire and acceptable people by the furnace of humiliation. It changes fire from final punishment to a trial that discloses steadfastness."}
{"connection_id": "BC-c826081ab2af17911724", "ref": "Sirach 4:1", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "withheld help makes needy eyes wait", "note": "The commentary places waiting beside a hand that withholds; Sirach forbids depriving the poor of life and making the needy person's eyes wait, showing how one person's grasping imposes another's patience."}
{"connection_id": "BC-3dc473cf043fe717cadb", "ref": "Sirach 4:28", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "standing for truth to death", "note": "The commentary has believers mutually enjoin truth and patience; Sirach urges striving for truth even to death and says God will fight for the faithful. It makes the cost of holding to truth explicit and joins it to trust in divine vindication."}
{"connection_id": "BC-8a26f02a29f55a7084b1", "ref": "Tobit 4:10", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "alms deliver from death", "note": "The commentary moves from hoarded goods to a person held toward death; Tobit says almsgiving delivers from death and keeps one from darkness, assigning the opened hand a rescuing effect."}
{"connection_id": "BC-ffd7f4d5a0ce1d0921b9", "ref": "Tobit 4:7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "give from possessions without turning away", "note": "The commentary's withholding hand closes before the needy; Tobit instructs his son to give alms from his possessions and not turn his face from the poor, joining family counsel to generosity."}
{"connection_id": "BC-6ba5d131e88b19812a8f", "ref": "WLC:1Kgs.2.36", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "Shimei ordered to remain in one city", "note": "The commentary's passive patient is held by another's command; Solomon orders Shimei to build a house in Jerusalem and stay there, making domestic residence a form of custody."}
{"connection_id": "BC-f8863ab5fb7fb69483fa", "ref": "WLC:1Kgs.2.42", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "king recalls oath tied to confinement", "note": "The commentary names a man compelled to swear and then held under another's control; Solomon reminds Shimei of the oath attached to his Jerusalem confinement after he crossed its boundary."}
{"connection_id": "BC-35a7a7e30b92c1c6c0b1", "ref": "WLC:1Kgs.2.46", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "confinement and oath end in execution", "note": "The commentary's coerced oath can converge with being held for death; Solomon orders Shimei executed after finding he violated the oath governing his residence."}
{"connection_id": "BC-4b45c91d3227d9c90e89", "ref": "WLC:1Kgs.8.31", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "oath imposed in a dispute", "note": "The commentary mentions a man made to swear by another; Solomon's prayer envisages an oath being laid on an accused man at the altar and asks God to judge, giving imposed swearing a judicial setting."}
{"connection_id": "BC-bb41f591be69c48ac245", "ref": "WLC:1Kgs.8.35", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's held grain and waiting community depend on what is released; Solomon envisions heaven restrained from rain because of sin and asks that prayer and repentance be heard, using עצר for divine withholding."}
{"connection_id": "BC-e174c8858b8178866761", "ref": "WLC:1Sam.14.24", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "an imposed oath", "note": "The commentary's B002 lexicographic example describes making another swear; Saul puts the troops under a curse-oath not to eat until evening. The scene makes restraint externally imposed and bodily costly rather than chosen self-discipline."}
{"connection_id": "BC-bf0471e544045ef63f04", "ref": "WLC:1Sam.14.24", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "food abstention under compulsion", "note": "The commentary's B015 source identifies fasting as a type of sabr because the self abstains; Saul's oath forces the troops to refrain from food until evening. The shared abstention sharpens the difference between a chosen fast and another person's command."}
{"connection_id": "BC-937289578f316e76460e", "ref": "WLC:1Sam.14.24", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "king imposes oath and food restraint", "note": "The commentary distinguishes chosen fasting from a man forcibly made to swear; Saul binds his troops with an oath not to eat until evening, turning restraint into an imposed burden."}
{"connection_id": "BC-0743ec75ee60985181e5", "ref": "WLC:1Sam.14.26", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fear of oath keeps hands from food", "note": "The commentary depicts forced oath and a restrained hand; Saul's troops see honey but no one puts a hand to his mouth because they fear the oath, showing bodily cost of imposed restraint."}
{"connection_id": "BC-7ca2da4aa13b30fbb3b9", "ref": "WLC:1Sam.14.44", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "oath threatens an unwitting eater with death", "note": "The commentary's forced oath and captive held for killing are separate senses of restraint; Saul's oath leads him to pronounce death on Jonathan for eating honey, showing how an imposed restraint can endanger a person."}
{"connection_id": "BC-1ef9d795a715c9f3fef1", "ref": "WLC:1Sam.14.45", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "community rescues person condemned by oath", "note": "The commentary makes endurance and right action communal; Saul's people refuse to let Jonathan die under the oath and rescue him, countering imposed restraint through collective intervention."}
{"connection_id": "BC-656c340ddff4e312e9d8", "ref": "WLC:1Sam.23.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "friend strengthens threatened man's hand", "note": "The commentary moves from a restraining hand to mutually commended endurance; Jonathan comes to David in danger and strengthens his hand in God, turning the hand into an image of encouragement."}
{"connection_id": "BC-873bd2d738a52f3c884a", "ref": "WLC:2Chr.16.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "divine eyes seek the loyal", "note": "The commentary's patient servant waits under divine sight; the seer says the Lord's eyes range through the earth to strengthen those fully loyal to him, making observation a source of support."}
{"connection_id": "BC-95f543eaa52164d5299e", "ref": "WLC:2Chr.18.15", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "compelling a prophet to swear truthfully", "note": "The commentary's B002 source gloss gives ṣabartu yamīnahu as making someone swear; Ahab asks how often he must adjure Micaiah to speak only truth in YHWH's name. This is a direct coercive-oath scene, unlike the surah's mutual counsel to truth."}
{"connection_id": "BC-e914d641621491efd617", "ref": "WLC:2Kgs.17.4", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's passive patient is confined by others; the Assyrian king confines Hoshea and binds him in prison, using Hebrew עצר for involuntary custody."}
{"connection_id": "BC-b76999b8d3f41a1f0fe4", "ref": "WLC:Amos.8.5", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "impatient merchants wait out rest to sell grain", "note": "The commentary sets patient communal restraint against the grasping hand and protected grain; merchants ask when the new moon and sabbath will end so they can sell grain with dishonest measures, turning waiting into greed."}
{"connection_id": "BC-7c65dfed9e3470e0ae0c", "ref": "WLC:Amos.8.6", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "buying the poor and selling inferior grain", "note": "The commentary's bad bargain and tight hand harm other people; Amos accuses merchants of buying the needy for silver and selling sweepings of wheat, joining unjust exchange to grain."}
{"connection_id": "BC-8bd6a1c30533284c064e", "ref": "WLC:Dan.3.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fidelity despite the fiery threat", "note": "The commentary's B013 gloss reads sabr as daring toward Fire, sarcastically of those choosing error; Daniel's three Judeans refuse the king's image even if God does not rescue them from the furnace. Their courage is fidelity under threat, a pointed contrast to defiant indifference toward punishment."}
{"connection_id": "BC-d96ba3e69db238845f0e", "ref": "WLC:Dan.3.18", "target": "sec4", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "facing fire for fidelity", "note": "The commentary's inverted patience is brazen acceptance of fire after a bad bargain; Daniel's companions refuse the idol even without rescue, making courage before threatened fire serve fidelity instead."}
{"connection_id": "BC-3fa151193cfff55563dd", "ref": "WLC:Dan.3.21", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "bound and thrown into the furnace", "note": "The commentary describes the person held for death and also develops courage toward fire; Daniel says the youths are bound and cast into the furnace, but later appear unbound. The narrative combines captors' restraint and fiery danger while reversing the expected death."}
{"connection_id": "BC-60d9c7f614102c8d6b56", "ref": "WLC:Dan.3.25", "target": "sec4", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "companions preserved in fire", "note": "The commentary's wrongdoers are daring toward punitive fire; in Daniel the king sees the faithful captives walking unharmed in the furnace, reversing the moral reason for facing fire and its outcome."}
{"connection_id": "BC-1759120830b428ef75c8", "ref": "WLC:Dan.7.13", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "Arabic ء ن س and Aramaic אנש; table sound correspondence", "note": "The commentary labels al-insān with root ء ن س as the human held for death; Aramaic bar ʾĕnāš in Daniel's vision is brought before the Ancient of Days and receives dominion. The table's sound candidate connects the human designation to an apocalyptic reversal, without proving cognacy."}
{"connection_id": "BC-2da86e1b1aed0e8e2335", "ref": "WLC:Dan.7.13", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ء ن س / Aramaic אנש, table sound correspondence", "note": "The commentary's insan is mortal and at risk of loss; Daniel sees a figure like a son of enash coming with the clouds toward the Ancient of Days, giving the human designation a strikingly exalted setting."}
{"connection_id": "BC-d0243480b6b894c02cfb", "ref": "WLC:Dan.7.14", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "kingdom granted to the humanlike figure", "note": "The commentary describes humanity in loss and then an exception; the figure introduced as a son of enash in the previous verse receives an enduring dominion here, making the reversal explicit."}

{"connection_id": "BC-c117f66d70d2a8af69ab", "ref": "WLC:Dan.7.25", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "holy ones handed over for a limited time", "note": "The commentary speaks of an afflicted group that must endure together; Daniel's arrogant king wears out the holy ones and they are given into his hand for a stated time before the kingdom changes hands."}
{"connection_id": "BC-b3dabf949cf2ddb1326f", "ref": "WLC:Dan.7.27", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "kingdom given to oppressed holy people", "note": "The commentary makes believing endurance the exception to human loss; after the preceding vision of oppression, Daniel gives the kingdom to the people of the holy ones, a corporate reversal of defeat."}
{"connection_id": "BC-0b9101fb62d1b20d0e1f", "ref": "WLC:Deut.11.17", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "ع ص ر / עצר, table sound match; shut rain", "note": "The commentary's asr includes holding back, and its grain is protected from loss; God warns that he may shut the heavens so rain and produce cease, using the table's Hebrew עצר correspondence for a communal loss of harvest."}
{"connection_id": "BC-dcf48aa8f3c94149898f", "ref": "WLC:Deut.15.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "closing the hand to the poor", "note": "The commentary's tight-handed asir keeps back what he can give; the law forbids hardening the heart or closing the hand against a poor brother."}
{"connection_id": "BC-6eb1c8ef3437dea25a54", "ref": "WLC:Deut.15.8", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "open hand and adequate loan", "note": "The commentary depicts the person who holds his hand against giving; this verse commands opening the hand and lending enough for the poor person's need."}
{"connection_id": "BC-edd72331e6f06261d2e3", "ref": "WLC:Deut.16.8", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's asr includes holding back; the seventh day is an עצרת, a restrained festival assembly in which no work is done, joining communal gathering to a prohibition on action."}
{"connection_id": "BC-fbda68815c1e188170b8", "ref": "WLC:Deut.21.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "limit on father's disposal of inheritance", "note": "The commentary pictures a father holding back what belongs to a son; the law bars a father from favoring a later son with the firstborn's portion, constraining paternal control of property."}
{"connection_id": "BC-ff68d926f4b9b4d7b324", "ref": "WLC:Deut.8.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "hunger teaches dependence beyond bread", "note": "The commentary places being restrained beside patient trust; Moses says God humbled Israel by hunger and fed it manna so it would learn to live by what comes from God's mouth, a communal education through withheld food."}
{"connection_id": "BC-00e149ffb8d6a57f7886", "ref": "WLC:Eccl.7.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "do not hasten to anger in spirit", "note": "The commentary makes patience the restraining of inner agitation; Ecclesiastes warns against being quick in spirit to anger because anger lodges with fools."}
{"connection_id": "BC-fe5a49f5a6d6a814a8da", "ref": "WLC:Esth.1.8", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "ء ن س / אנס, table sound match; compulsion, not human cognate", "note": "The commentary's forced oath shows one person restraining another; Esther's banquet rule says drinking is without compulsion, a specific reversal of social coercion, though the act is drinking rather than swearing and the Hebrew root is not used for a human being."}
{"connection_id": "BC-04f0198b26c04bd0fd36", "ref": "WLC:Esth.4.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "communal fast before a risk of death", "note": "The commentary's B015 gloss calls fasting a form of self-restraint; Esther asks the Jews to fast for three days before she approaches the king despite the death penalty. The fast becomes communal preparation and solidarity before a lethal risk."}
{"connection_id": "BC-f83fc06940704282bddd", "ref": "WLC:Exod.17.12", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "hands held steady until sunset", "note": "The commentary distinguishes a person holding himself from another holding his hand, then extends patience to a group; Aaron and Hur physically support Moses' tired hands until sunset while the people endure battle."}
{"connection_id": "BC-9f901e269a5521270b97", "ref": "WLC:Exod.34.6", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "God slow to anger after rebellion", "note": "The commentary makes patience restraint and waiting for judgment; after Israel's breach, God describes himself as slow to anger and abundant in steadfast love. It adds divine patience as the quality that makes judgment and renewed relationship coexist."}
{"connection_id": "BC-0c8cd53dbef04f8450d5", "ref": "WLC:Ezek.28.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "corrupt trade ends in fire", "note": "The commentary's bad exchange is followed by daring toward fire; Ezekiel condemns unjust trading and says fire will come from the trader's midst and consume him, bringing commerce and punishment into one verse."}
{"connection_id": "BC-9fe603d072d20ee04d6a", "ref": "WLC:Gen.16.2", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's asr can enclose a girl at reproductive maturity; Sarai says the Lord has restrained her from bearing children, using עצר for an involuntary bodily restriction rather than household confinement."}
{"connection_id": "BC-95dcd2c838cbbcf4f0e6", "ref": "WLC:Gen.20.18", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "Arabic ع ص ر and Hebrew עצר; table sound candidate only", "note": "The commentary labels al-ʿaṣr B006 as restraint and al-muʿṣir B009 as a girl held indoors; Hebrew עצר here says God closed every womb in Abimelech's house. The table's sound correspondence supplies a bodily restraint comparison, but this is reproductive stoppage, not menstrual confinement."}
{"connection_id": "BC-46bc73a3dc5ea8e6dcf9", "ref": "WLC:Gen.20.18", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's house-held girl connects enclosure with reproduction; God has closed the wombs throughout Abimelech's household because of Sarah, using עצר for reproductive restraint, a different subject and cause."}
{"connection_id": "BC-a465711b155b73fc6e76", "ref": "WLC:Gen.22.12", "target": "sec4", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "father does not withhold son", "note": "The commentary names a father holding back his son's property; the angel says Abraham has not withheld his son from God, reversing the direction and object of a father's withholding."}
{"connection_id": "BC-e8b8873ba147f540fde4", "ref": "WLC:Gen.22.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "binding before a near-sacrifice", "note": "The commentary describes al-maṣbūra as one kept for death; in the Aqedah Abraham binds Isaac and places him on the altar before the killing is stopped. The scene gives a specific near-sacrifice example while preserving the difference that Isaac is spared."}
{"connection_id": "BC-b550df439410f21f6fbc", "ref": "WLC:Gen.41.36", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "stored grain reserved through famine", "note": "The commentary's enclosed grain is kept for safety; Joseph proposes keeping grain as a reserve for famine so the land will not perish, shifting protection from a husk to a storehouse."}
{"connection_id": "BC-4f426af370a99f30b6e3", "ref": "WLC:Gen.41.49", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "Arabic ص ب ر and Hebrew צבר; table sound candidate only", "note": "The commentary labels ṣabr B001 as self-restraint and separately describes grain kept in its husk as ʿaṣr B010; Hebrew צבר here is Joseph piling up grain for famine stores. Accumulation is a specific neighboring sense of retaining grain, though Joseph's public reserve differs from miserly withholding and cognacy is unverified."}
{"connection_id": "BC-2a81e9c06f25ab41c27a", "ref": "WLC:Gen.41.49", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "grain amassed beyond counting", "note": "The commentary's grain is something held in reserve; Joseph stores so much grain that it becomes uncountable, a beneficial form of withholding set against the commentary's selfish tight hand."}
{"connection_id": "BC-1045ce195358e80fc8a5", "ref": "WLC:Hab.2.10", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "hoarder's plan costs his own life", "note": "The commentary's possessor becomes the one in loss; Habakkuk says the plan to cut off many peoples has brought shame on the house and forfeited its maker's life, undoing the security sought in the prior verse."}
{"connection_id": "BC-14cb3ca842f64f27bd04", "ref": "WLC:Hab.2.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "waiting for the appointed vision", "note": "The commentary defines sabr as waiting for the Lord's decree; Habakkuk says the vision has an appointed time and, even if it seems delayed, the hearer must wait for it. It makes delay part of the promise rather than evidence that it failed."}
{"connection_id": "BC-ae7c0db24444756e21fe", "ref": "WLC:Hab.2.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "wait for the delayed appointed time", "note": "The commentary presents patience as waiting for the Lord's decision; Habakkuk says the vision has an appointed time and instructs the hearer to wait even if it delays."}
{"connection_id": "BC-c71de3ee1b2fa9819891", "ref": "WLC:Hab.2.4", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "faithfulness amid the delayed vision", "note": "The commentary joins belief to patience as the exception to loss; Habakkuk contrasts the proud person's disordered soul with the righteous one who lives by faithfulness in the delay described just before."}
{"connection_id": "BC-200ee0568ab76396b0fe", "ref": "WLC:Hab.2.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "unjust gain used to build a safe nest", "note": "The commentary's withholding hand tries to protect what it has gathered; Habakkuk condemns one who gains evil profit for his house to place his nest high beyond disaster."}
{"connection_id": "BC-6ca4ab58151b96947d51", "ref": "WLC:Isa.1.13", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's collective patience joins moral action to communal holding; God rejects an עצרה, a solemn assembly, when worship is mixed with injustice, warning that the gathered form alone does not suffice."}
{"connection_id": "BC-10ea036395ff3ed9ad11", "ref": "WLC:Isa.28.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "one who trusts need not hurry", "note": "The commentary sets belief and patient restraint against the human being's haste; Isaiah says the person who trusts the tested foundation will not be hurried, joining trust to freedom from panic."}
{"connection_id": "BC-3b111ad6d9ca5d2db264", "ref": "WLC:Isa.28.28", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "grain is crushed but not endlessly", "note": "The commentary's grain is protected in its covering; Isaiah distinguishes grain processing from destruction, saying it is threshed but not pulverized forever, an agricultural counterpart to protection before use."}
{"connection_id": "BC-74b1f4a1e8f6f17cab51", "ref": "WLC:Isa.30.15", "target": "sec4", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "quiet trust offered but refused", "note": "The commentary says salvation belongs to those who restrain themselves in faith; God tells Judah that quietness and trust would be their strength, then says they were unwilling, making refusal of patience explicit."}
{"connection_id": "BC-d21ce4cc3d93623f07b1", "ref": "WLC:Isa.30.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "flight chosen instead of stillness", "note": "The commentary's hasty human will not hold himself; Judah chooses swift horses rather than quiet trust and is told that flight and pursuit will follow, a concrete outcome of the refusal in the previous verse."}
{"connection_id": "BC-b7979888047eccba156d", "ref": "WLC:Isa.30.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "the Lord waits to show grace and blesses those who wait", "note": "The commentary has the prophet wait for the Lord's decree and says the waiting person remains in God's sight; Isaiah says the LORD waits to show grace and blesses those who wait for him. The two-sided waiting makes delay a merciful encounter."}
{"connection_id": "BC-a73f4584a5dfc5c69f14", "ref": "WLC:Isa.30.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "waiting for grace rather than immediate judgment", "note": "The commentary's waiting sabr is directed toward God's ruling; Isaiah links the Lord's own waiting to grace. This adds the specific reading of divine delay as mercy, distinct from the verse's reciprocal pattern of the Lord and people waiting."}
{"connection_id": "BC-e96de667239eafb5e37b", "ref": "WLC:Isa.35.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "strengthen weak hands", "note": "The commentary moves from a person's restraining hand to mutual encouragement; Isaiah commands hearers to strengthen weak hands, making the community's support of frail members concrete."}
{"connection_id": "BC-da7a60697cb00f6062e7", "ref": "WLC:Isa.35.4", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "say to the anxious to be strong", "note": "The commentary's believers recommend patience to one another under divine care; Isaiah tells them to address fearful hearts with courage and the promise that God will come and save."}
{"connection_id": "BC-73c35c23ad3a88a74575", "ref": "WLC:Isa.49.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "prisoners told to come out", "note": "The commentary's passive patient is held by another; the servant's commission includes telling prisoners to come out and those in darkness to show themselves, reversing enforced enclosure."}
{"connection_id": "BC-c5a1f5749a531a6ffabc", "ref": "WLC:Isa.50.11", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "walking by one's self-kindled fire", "note": "The commentary links a ruinous choice to apparent boldness before fire; those who kindle their own fire are told to walk by its flames and will lie down in torment, making the chosen flame a judgment."}
{"connection_id": "BC-3618a7862d5ab8af9811", "ref": "WLC:Isa.51.12", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fear of dying mortal against divine comfort", "note": "The commentary calls the human being frail and liable to loss; God asks why the comforted people fear mortal enosh who dies like grass, while divine reassurance remains available."}
{"connection_id": "BC-fca1f9eada2230f3e7f4", "ref": "WLC:Isa.53.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "held for slaughter, silent under oppression", "note": "The commentary's B002 gloss describes the one held for death; Isaiah's servant is oppressed and led like a lamb to slaughter, yet does not open his mouth. The verse brings external restraint and inward silence together in one figure."}

{"connection_id": "BC-dc319ed8ccb17dc49489", "ref": "WLC:Isa.53.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "led to slaughter yet silent", "note": "The commentary's passive captive is held for killing, while its patient person withholds an outcry; the servant is led like a lamb to slaughter and does not open his mouth, joining both positions in one scene."}
{"connection_id": "BC-71b066430a25afdf69e8", "ref": "WLC:Isa.58.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "self-denial with oppression", "note": "The commentary makes fasting a kind of self-restraint yet warns about holding others; Isaiah rebukes fasters who pursue their own business and oppress workers on the fast day, exposing the split between the two acts."}
{"connection_id": "BC-b837c9786c06d4e49829", "ref": "WLC:Isa.58.6", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fasting as releasing others", "note": "The commentary calls fasting restraint of one's own self; Isaiah says the fast God chooses loosens wicked bonds and frees the oppressed. The prophetic text redirects attention from self-denial toward releasing people held by others."}
{"connection_id": "BC-cd17792cdea2dca3bd16", "ref": "WLC:Isa.58.6", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fast that releases bonds", "note": "The commentary calls fasting one form of holding the self and also depicts a person held against his will; Isaiah calls for a fast that loosens bonds and frees the oppressed, joining the two types of holding ethically."}
{"connection_id": "BC-2039d99382d6e8e925e5", "ref": "WLC:Isa.58.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fasting as opening the hand", "note": "The commentary describes the miserly hand withholding wealth and grain; Isaiah's fast includes sharing bread with the hungry and bringing the homeless poor into one's house. It turns restraint from consumption into generosity toward others."}
{"connection_id": "BC-72205c8d484f5c47de4a", "ref": "WLC:Isa.58.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fast joined to sharing bread", "note": "The commentary juxtaposes fasting as restraint and the hand that withholds what it could give; Isaiah's chosen fast requires sharing bread with the hungry and bringing the homeless in."}
{"connection_id": "BC-5c6ea694dc640796205f", "ref": "WLC:Isa.66.24", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "unquenched fire and the fate of rebels", "note": "The commentary cites the question of how daring people are toward Fire as a warning about punishment; Isaiah ends with observers seeing the corpses of rebels where the worm does not die and the fire is not quenched. It specifies the irreversible judgment behind the fire image."}
{"connection_id": "BC-addb76a1e9b82c4f7cd7", "ref": "WLC:Jer.33.1", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary pairs being held with a divine word received while waiting; Jeremiah is still confined in the court of the guard when the Lord's word comes to him, using עצר for custody."}
{"connection_id": "BC-805420546b99c3b13b63", "ref": "WLC:Jer.36.5", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "confined speaker sends his words outward", "note": "The commentary contrasts a held person with mutually recommended truth; Jeremiah says he is detained and cannot enter the Lord's house, then instructs Baruch to read his scroll there, showing testimony moving despite confinement."}
{"connection_id": "BC-acb68ae64e68b703d1c8", "ref": "WLC:Jer.38.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "Jeremiah lowered into a cistern to die", "note": "The commentary's B002 image is a person held for death; Ebed-Melech says Jeremiah was put in the cistern to die of hunger because no bread remained. The verse supplies an explicit instance of detention with death as its intended outcome."}
{"connection_id": "BC-6bccde4d504c8af95368", "ref": "WLC:Job.13.15", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "hope under threat, with a textual split", "note": "The commentary treats sabr as waiting for God's judgment; Job speaks under threat of being killed, but WLC's ketiv לֹא reads no hope while its qere לוֹ supports hoping in God. The verse holds protest and patient trust together without resolving the textual alternative."}
{"connection_id": "BC-458b2d094d2d5d7a89b0", "ref": "WLC:Job.2.10", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "receiving adversity without speech against God", "note": "The commentary glosses sabr as holding oneself back from panic or lament; after Job's losses he refuses his wife's counsel to curse God and does not sin with his lips. Job supplies a concrete response to calamity through restrained speech."}
{"connection_id": "BC-39078f79c1c2095f16eb", "ref": "WLC:Job.2.10", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "accept adversity without sinful speech", "note": "The commentary defines patience as holding back lament under misfortune; Job rebukes his wife's counsel and accepts adversity from God without sinning with his lips in this scene."}
{"connection_id": "BC-1d4ed3fcf3affc8ef18b", "ref": "WLC:Job.27.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "wicked heaps silver like dust", "note": "The commentary's withholding hand accumulates goods under threat of loss; Job says the wicked may heap up silver like dust, using צבר, the table's sound match to ص ب ر with the distinct sense of accumulation."}
{"connection_id": "BC-d2f98e180eb28beae979", "ref": "WLC:Job.27.17", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "stored goods pass to the innocent", "note": "The commentary's human holder cannot keep his gain secure; Job says the innocent will divide the wicked person's silver, reversing the hoard described in the preceding verse."}
{"connection_id": "BC-8eb77ec5a191e77e139e", "ref": "WLC:Job.29.9", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "princes put hand over mouth", "note": "The commentary places the holding hand alongside restraint of the person; Job recalls princes stopping their words and putting a hand over their mouth, a visible enactment of self-control."}
{"connection_id": "BC-ad894d8e49aa845b406c", "ref": "WLC:Job.4.17", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ء ن س / אנש, table sound correspondence with BDB Arabic note", "note": "The commentary's insan is in loss except for right action; Eliphaz asks whether mortal enosh can be righteous before God, pressing the frail human term into a question about moral standing."}
{"connection_id": "BC-04d4f67ac54429d5b755", "ref": "WLC:Job.4.2", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ع ص ر / עצר, table sound correspondence", "note": "The commentary's asr includes restraining; Eliphaz asks who can restrain words when provoked, using Hebrew עצר for the failure of verbal self-control."}
{"connection_id": "BC-bedee1958ac9e2ea7647", "ref": "WLC:Job.7.17", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ء ن س / אנש, table sound correspondence with BDB Arabic note", "note": "The commentary's insan is one held under divine judgment; Job asks why God makes so much of mortal enosh and sets his heart on him, casting close attention as oppressive in his suffering."}
{"connection_id": "BC-380aa84721a16f419d77", "ref": "WLC:Job.7.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "being inspected every morning", "note": "The commentary says the patient waits under God's eyes as protection; Job complains that God visits and tests him every morning, preserving a contrary experience of divine surveillance."}
{"connection_id": "BC-538cf6ca422e3bdb65fc", "ref": "WLC:Joel.2.15", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fast and solemn assembly", "note": "The commentary extends self-restraint from a person to a community; Joel orders a sanctified fast and calls a solemn assembly, using the table's Hebrew עצר family for the collective gathering."}
{"connection_id": "BC-511ef320e358ed624f53", "ref": "WLC:Joel.2.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "whole household called out to assembly", "note": "The commentary expands holding to a community and evokes domestic enclosure; Joel summons elders, children, nursing infants and even bride and groom from their rooms, showing the fast superseding ordinary household boundaries."}
{"connection_id": "BC-4c86bdf2048d1e463597", "ref": "WLC:Jonah.2.1", "target": "sec4", "tradition": "tevrat", "kind": "paralel", "basis": "fish holds Jonah", "note": "The commentary invokes the fish's owner as the example a patient prophet must avoid; the Hebrew story first has a great fish swallow Jonah, making his literal confinement the setting of that warning."}
{"connection_id": "BC-93504a53ec8dfec0c554", "ref": "WLC:Jonah.2.2", "target": "sec4", "tradition": "tevrat", "kind": "paralel", "basis": "Jonah prays from inside fish", "note": "The commentary recalls the fish's owner crying out while constrained; in Hebrew verse numbering Jonah prays to the Lord from the fish's belly, turning confinement into an appeal."}
{"connection_id": "BC-cfdaee6b6ea34cbadf61", "ref": "WLC:Jonah.2.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "Jonah's distress-call", "note": "The commentary cites Jonah as the prophet who called out while constricted and warns against his response; WLC Jonah records his prayer beginning with a call from distress in the fish, followed by God's answer. The shared scene exposes the difference between a distress-call and the commentary's demand to wait."}
{"connection_id": "BC-7f1ea964af226fc59dd0", "ref": "WLC:Jonah.4.9", "target": "sec4", "tradition": "tevrat", "kind": "paralel", "basis": "Jonah's anger unto death", "note": "The commentary warns the waiting prophet not to be like the constricted fish's owner; later Jonah tells God he is angry enough to die, identifying the uncontrolled reaction at issue."}
{"connection_id": "BC-a96c5127440a3ce10cea", "ref": "WLC:Judg.11.35", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "father's vow constrains daughter's future", "note": "The commentary places a girl under a father's control and also describes forced oath; Jephthah tells his daughter he has vowed to the Lord and cannot take it back, so his own oath determines her fate, though she did not swear it."}
{"connection_id": "BC-3332c4c7dfca40898de0", "ref": "WLC:Lam.3.26", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "quiet waiting amid affliction", "note": "The commentary opposes sabr to panic and describes waiting for the Lord's judgment; Lamentations says it is good to wait quietly for the LORD's salvation in the aftermath of Jerusalem's ruin. It gives restrained waiting a voice within communal catastrophe."}
{"connection_id": "BC-b14dda23b25eba84bab9", "ref": "WLC:Lam.3.26", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "quiet waiting for deliverance", "note": "The commentary defines patience as waiting under God's judgment without outcry; Lamentations calls it good to wait quietly for the Lord's salvation amid suffering."}
{"connection_id": "BC-af3b16833970f5c2dfa8", "ref": "WLC:Lam.3.28", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "sitting alone in silence under imposed burden", "note": "The commentary distinguishes holding oneself from being held by another; the sufferer is told to sit alone and silent because a yoke has been laid on him, holding both experiences together."}
{"connection_id": "BC-21a4df9359c98d6c3cb8", "ref": "WLC:Lam.3.29", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "mouth put in dust while hope remains", "note": "The commentary describes patience as holding back the cry while awaiting deliverance; after the instruction to sit silently under a yoke, Lamentations bids the sufferer put his mouth in dust because hope may remain."}
{"connection_id": "BC-69323ce64d8a04a9aee6", "ref": "WLC:Lev.15.19", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "menstrual separation, with a difference", "note": "The commentary's B009 source gloss calls a young woman held at home at first menses; Leviticus gives a menstruating woman seven days of impurity and rules for contact, but does not say she is confined indoors. It is a concrete ritual frame for bodily separation, not evidence of the same social practice."}
{"connection_id": "BC-6f21b2add389596e99d3", "ref": "WLC:Lev.15.19", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "menstruation imposes contact limits", "note": "The commentary's newly menstruating girl is held inside a house; the law assigns seven days of menstrual impurity and limits contact, supplying a ritual background for seclusion without itself ordering house confinement."}
{"connection_id": "BC-5e5e7272bda5bedad9b0", "ref": "WLC:Lev.16.29", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "ritual self-affliction", "note": "The commentary's B015 source connects fasting with holding oneself back; Leviticus commands the community to afflict itself on the Day of Atonement and cease work. It places bodily restraint within a collective ritual; the verse itself says self-affliction rather than explicitly naming a fast."}
{"connection_id": "BC-eb45ce62551bd1a766ee", "ref": "WLC:Lev.19.17", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "reprove neighbor instead of harboring wrong", "note": "The commentary's mutual counsel requires another person's good; the law commands frank correction of a neighbor rather than silently bearing sin on his account."}
{"connection_id": "BC-a34266c2e65532ab4148", "ref": "WLC:Lev.23.36", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "festival assembly with forbidden work", "note": "The commentary allows holding to describe a whole community; the eighth-day sacred assembly, called עצרת from the table's Hebrew עצר family, is paired with a ban on ordinary work."}
{"connection_id": "BC-826b1ed735d058069390", "ref": "WLC:Neh.5.11", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "restore fields, houses and interest", "note": "The commentary's father-and-son property scene raises goods held from rightful users; Nehemiah demands that lenders return debtors' fields and houses and remit the interest, providing a communal remedy for the grasping hand."}
{"connection_id": "BC-806a01ef2695d0e1577b", "ref": "WLC:Neh.5.5", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "children enslaved under household debt", "note": "The commentary links a father's control of goods to the person forcibly held; indebted families say their daughters are already enslaved and their fields belong to others, showing a household's loss of both property and freedom."}
{"connection_id": "BC-5581d0c398cf268af203", "ref": "WLC:Num.30.4", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "daughter's vow in father's house", "note": "The commentary's newly menstruating girl is kept at home; this law situates a young woman's vow while she remains in her father's house, where his authority can affect her commitment."}
{"connection_id": "BC-3a6431a56a779814bb5d", "ref": "WLC:Num.30.6", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "father restrains daughter's vow", "note": "The commentary's held girl is subject to a household's control; the father can forbid the vow he hears and the daughter is released from it, a concrete form of paternal restraint in that house."}

{"connection_id": "BC-5e1c2d19cf6c30400625", "ref": "WLC:Prov.1.19", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "unjust gain takes the owner's life", "note": "The commentary's bargain for error leads to loss; the proverb says ill-gotten gain takes away the life of its possessors, making acquisition turn against the acquirer."}
{"connection_id": "BC-70ad5a6935169f6549a7", "ref": "WLC:Prov.11.24", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "withholding and poverty", "note": "The commentary calls the withholding hand miserly and cites the human who holds back from spending; Proverbs says one who withholds what should be given comes to want. It makes retention itself a path into the loss the surah announces."}
{"connection_id": "BC-b782f99d9910454fc2e3", "ref": "WLC:Prov.11.24", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "wrongful withholding leads to want", "note": "The commentary links the tight hand to the human being in loss; this proverb says one person withholds what ought to be given and comes to want, giving that loss an economic form."}
{"connection_id": "BC-739c5eb2d0723095b1ff", "ref": "WLC:Prov.13.11", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "gradual gathering versus hasty wealth", "note": "The commentary sets patient holding beside grasping gain; the proverb says wealth gained hastily shrinks while one who gathers little by little increases it, assigning different outcomes to two tempos of acquisition."}
{"connection_id": "BC-7eb294bbdded8a563236", "ref": "WLC:Prov.13.22", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "inheritance left to descendants", "note": "The commentary names a father withholding a son's goods; the proverb praises a good person who leaves an inheritance to grandchildren, a long view of wealth passed on rather than retained."}
{"connection_id": "BC-fc4529a7e7b9786d3d89", "ref": "WLC:Prov.14.29", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "slow anger versus hasty folly", "note": "The commentary's patience is the contrary of impulsive human outcry; the proverb contrasts a person slow to anger with one quick tempered who exalts folly."}
{"connection_id": "BC-509a2c68b23ef9e25d9d", "ref": "WLC:Prov.16.32", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "rule of spirit over conquest", "note": "The commentary glosses sabr as holding oneself back from panic; Proverbs ranks slowness to anger above military might and ruling one's spirit above capturing a city. It makes self-restraint a form of strength rather than domination."}
{"connection_id": "BC-fb6d480c63cd52f02101", "ref": "WLC:Prov.16.32", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "mastering one's spirit", "note": "The commentary makes patience the act of holding one's own self; the proverb ranks the person who rules his spirit above a conqueror, turning restraint into strength."}
{"connection_id": "BC-ccd8646f4a20ddd899e8", "ref": "WLC:Prov.21.13", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "closed ear later cries unheard", "note": "The commentary says humans cry out under harm yet withhold good when they have it; the proverb warns that one who shuts his ear to the poor person's cry will cry out and receive no answer."}
{"connection_id": "BC-db1a837ce517cfcf188a", "ref": "WLC:Prov.21.26", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "righteous gives without withholding", "note": "The commentary's asir is marked by a hand held closed; the righteous person in this proverb gives and does not hold back, after the preceding clause describes craving all day."}
{"connection_id": "BC-9d2a4b53227bdb43d013", "ref": "WLC:Prov.25.28", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "self-control as a wall", "note": "The commentary contrasts the self-held person with the person held by others; Proverbs likens a person without self-control to a breached city without walls. The image makes restraint protection against becoming capturable."}
{"connection_id": "BC-7ffeb585996893e01274", "ref": "WLC:Prov.25.28", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "uncontrolled spirit and breached city", "note": "The commentary contrasts self-restraint with being held by another; this proverb pictures a person without control of spirit as a city without walls, exposed precisely because the inner guard is absent."}
{"connection_id": "BC-20967f629541ec6c68de", "ref": "WLC:Prov.29.11", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "venting versus holding back", "note": "The commentary's B001 gloss says sabr holds the self back from panic or outcry; Proverbs contrasts a fool who vents his whole spirit with a wise person who stills it. This is a direct wisdom parallel for keeping an impulse from spilling out."}
{"connection_id": "BC-38aa85df2712c04a7b13", "ref": "WLC:Prov.3.27", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "withholding good within one's power", "note": "The commentary calls the withholding hand a form of asr; the proverb forbids keeping good from those to whom it is due when one's hand has power to do it."}
{"connection_id": "BC-1cc22df1c0f5941fce6a", "ref": "WLC:Prov.5.22", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "wrongdoer held by cords of his sin", "note": "The commentary says each person is held to what he has earned; the proverb makes that relation physical when the wicked person's own iniquities ensnare him and the cords of his sin hold him fast."}
{"connection_id": "BC-943d100db692f83e741b", "ref": "WLC:Prov.6.27", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "fire held against the chest", "note": "The commentary's phrase about daring toward fire exposes the folly of accepting destructive consequences; the proverb asks whether one can carry fire against the chest without burning one's clothes, in its context a warning against adultery."}
{"connection_id": "BC-2661125222061e926bf1", "ref": "WLC:Ps.103.15", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ء ن س / אנש, table sound correspondence with BDB Arabic note", "note": "The commentary's insan stands inside passing time; the psalm compares the days of mortal enosh to grass and a field flower, making human duration visibly fragile."}
{"connection_id": "BC-cdfb766a7bce2a00410a", "ref": "WLC:Ps.130.5", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "waiting in the divine word", "note": "The commentary explains sabr as waiting for the Lord's decree; the psalmist waits for the LORD and hopes in his word. It gives the waiting stance a textual object and a first-person prayer form."}
{"connection_id": "BC-212b9a1b7294dd215401", "ref": "WLC:Ps.131.2", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "quieting one's own soul", "note": "The commentary defines patience as keeping the self from outcry; the psalmist says he has calmed and quieted his soul like a weaned child, giving that inner action a concrete image."}
{"connection_id": "BC-8c65d83b3f3c14a88a12", "ref": "WLC:Ps.142.8", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "prisoner asks release and righteous company", "note": "The commentary's held person needs both rescue and the community's patient support; in Hebrew verse numbering the psalmist asks to be brought out of confinement so he can praise God among the righteous."}
{"connection_id": "BC-e5d1e83588ca06646e58", "ref": "WLC:Ps.33.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "the eye of God on those who wait", "note": "The commentary quotes the prophet told to be patient because he is in God's eyes; this psalm places the LORD's eye on those who hope in his steadfast love. It joins waiting with being watched, rather than leaving patience as an unseen private effort."}
{"connection_id": "BC-732799199477defb02a5", "ref": "WLC:Ps.33.18", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "Lord's eye on those who wait", "note": "The commentary tells the waiting prophet that he is under God's eyes; this psalm says the Lord's eye rests on those who fear him and wait for his faithful love, joining watchfulness to expectation."}
{"connection_id": "BC-49b325b6417df5700ce0", "ref": "WLC:Ps.37.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "be still while waiting for the Lord", "note": "The commentary says waiting is a form of patience under divine judgment; the psalm orders the hearer to be still before the Lord and wait rather than fret over a prospering schemer."}
{"connection_id": "BC-14049b9b4186948c2ced", "ref": "WLC:Ps.39.2", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "guarding mouth under distress", "note": "The commentary's patient person holds the self back from lament; the psalmist resolves to muzzle his mouth while the wicked stand before him, an intentional restraint of speech."}
{"connection_id": "BC-3e6ea2f16e7d71a6e622", "ref": "WLC:Ps.39.7", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "mortal man heaps wealth without knowing heir", "note": "The commentary's tight hand is set beside humanity's loss; this psalm says a person heaps wealth without knowing who will gather it, using צבר, the table's sound match to ص ب ر, here meaning accumulation rather than patience."}
{"connection_id": "BC-1a43c4a52d7e2d324f1a", "ref": "WLC:Ps.39.8", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "wait for God after futile hoarding", "note": "The commentary opposes possessive holding to patient waiting; immediately after describing a person heaping goods without knowing their heir, the psalmist asks what he waits for and names God as hope."}
{"connection_id": "BC-1a3848e353d0b0bffeaf", "ref": "WLC:Ps.40.2", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "patient waiting for the LORD", "note": "The commentary calls sabr a wait for the Lord's judgment; the psalmist says he waited patiently for the LORD, who inclined to hear his cry. This gives waiting an urgent prayer setting rather than making it a general disposition."}
{"connection_id": "BC-88c68988ab87b5eff076", "ref": "WLC:Ps.40.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "rescue from the pit", "note": "The commentary sets self-restraint beside being held by another; the next verse says the LORD draws the psalmist from a destructive pit and mud. This supplies a specific image of release from confinement, distinct from the preceding verse's patient wait."}
{"connection_id": "BC-50af9457b6a9c96ac005", "ref": "WLC:Ps.79.11", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "prisoners groan and are marked for death", "note": "The commentary's passive patient is someone held for killing; the psalm asks God to hear imprisoned people's groans and preserve those appointed to die, adding a plea for release to the captive scene."}
{"connection_id": "BC-f6df1d0c85d525d31e78", "ref": "WLC:Ps.8.5", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "ء ن س / אנש, table sound correspondence with BDB Arabic note", "note": "The commentary's insan is vulnerable to loss yet addressed by divine care; the psalm asks why God remembers mortal enosh, setting human frailty beside God's attention."}
{"connection_id": "BC-75215da9711be887c18a", "ref": "WLC:Ps.90.4", "target": "sec4", "tradition": "tevrat", "kind": "soydas", "basis": "Arabic ء ن س and Hebrew אנש; table correspondence, BDB notes Arabic", "note": "The commentary explicitly labels al-insān with Arabic root ء ن س and reads the human as death-bound; Hebrew אֱנוֹשׁ in this verse is returned to dust. The table treats אנש as a regular sound correspondence and notes BDB's Arabic cognate, giving the human term a specifically mortal setting."}
{"connection_id": "BC-e14eb549efc931a23414", "ref": "WLC:Zech.8.16", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "speak truth to one another", "note": "The commentary's exception to loss includes mutual counsel in truth; Zechariah commands people to speak truth with their neighbors and render true judgments for peace, giving that counsel a public setting."}
{"connection_id": "BC-25cdc24837e4f5ddd1e6", "ref": "WLC:Zech.8.17", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "harmful designs and false oaths rejected", "note": "The commentary's communal truth-telling stands beside a coerced oath; Zechariah forbids plotting evil against a neighbor and loving a false oath, guarding the group against speech used to injure."}
{"connection_id": "BC-82a7bc5e1f22069d4b5f", "ref": "WLC:Zech.9.3", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "Tyre heaps wealth behind a fortress", "note": "The commentary associates protected stores with a potentially grasping hand; Tyre builds a stronghold and heaps silver and gold like dust, using צבר, the table's sound match to ص ب ر with the distinct sense of piling up."}
{"connection_id": "BC-127625c336eb056bc52a", "ref": "WLC:Zech.9.4", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "stored wealth lost and city consumed by fire", "note": "The commentary links hoarding with ultimate fire; after Tyre's fortified accumulation, the Lord strips its wealth and fire consumes it, showing how a guarded store fails."}
{"connection_id": "BC-fa84b20380ed45df7e03", "ref": "Wisdom 2:20", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "righteous person condemned to death", "note": "The commentary's B002 gloss describes a person held for death; Wisdom says the ungodly plot to condemn the righteous person to a shameful death because his life differs from theirs. It makes the held victim's righteousness, rather than guilt, the occasion for the sentence."}
{"connection_id": "BC-22cb83284e0ef034c9bd", "ref": "Wisdom of Solomon 2:19", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "torturers test a righteous person's forbearance", "note": "The commentary's captive held for killing and the patient person can be the same individual; the wicked propose tormenting the righteous man to test his gentleness and forbearance."}
{"connection_id": "BC-18bd0ac0c6ddd235a84c", "ref": "Wisdom of Solomon 2:20", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "righteous person condemned to shameful death", "note": "The commentary's passive patient is restrained toward death; the wicked resolve to condemn the tested righteous man to a shameful death while claiming God will protect him, making the test lethal."}
{"connection_id": "BC-51a23072a5dab4967006", "ref": "Wisdom of Solomon 3:1", "target": "sec4", "tradition": "tevrat", "kind": "motif", "basis": "the righteous held in God's hand", "note": "The commentary cites the soul as pledged for what it earns; Wisdom says the souls of the righteous are in God's hand and no torment touches them. It turns being held from punitive custody into protection, qualifying a simple reading of captivity."}
{"connection_id": "BC-84d3f42dd299e723e725", "ref": "b. Shabbat 88b", "target": "sec4", "tradition": "tevrat", "kind": "yorum_gelenegi", "basis": "enduring insult without answering", "note": "The commentary glosses sabr as holding oneself back from panic or outcry; the Talmud praises people who suffer insult without insulting back or replying. Its reading of the lovers of God in Judges 5:31 turns restraint under humiliation into a sign of devotion."}

